function solve(s) {
  const chars = [];
  const counts = [];
  for (let i = 0; i < s.length; i++) {
    let found = -1;
    for (let t = 0; t < chars.length; t++) {
      if (chars[t] === s[i]) {
        found = t;
        break;
      }
    }
    if (found === -1) {
      chars.push(s[i]);
      counts.push(1);
    } else {
      counts[found]++;
    }
  }
  const order = [];
  for (let i = 0; i < chars.length; i++) order.push([chars[i], counts[i]]);
  for (let i = 1; i < order.length; i++) {
    const cur = order[i];
    let j = i - 1;
    while (j >= 0 && (order[j][1] < cur[1] || (order[j][1] === cur[1] && order[j][0] > cur[0]))) {
      order[j + 1] = order[j];
      j--;
    }
    order[j + 1] = cur;
  }
  let out = "";
  for (let i = 0; i < order.length; i++) {
    for (let r = 0; r < order[i][1]; r++) out += order[i][0];
  }
  return out;
}

function solve(s) {
  const n = s.length;
  const counts = new Array(128).fill(0);
  for (let i = 0; i < n; i++) counts[s.charCodeAt(i)]++;
  const buckets = [];
  for (let f = 0; f <= n; f++) buckets.push([]);
  for (let code = 0; code < 128; code++) {
    if (counts[code] > 0) buckets[counts[code]].push(code);
  }
  let out = "";
  for (let f = n; f >= 1; f--) {
    const bucket = buckets[f];
    bucket.sort((a, b) => a - b);
    for (let t = 0; t < bucket.length; t++) {
      for (let r = 0; r < f; r++) out += String.fromCharCode(bucket[t]);
    }
  }
  return out;
}
